"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io


def parse_feed(text):
    text = text.lstrip("\ufeff")
    rows = csv.DictReader(io.StringIO(text))
    if rows.fieldnames:
        rows.fieldnames = [name.strip() for name in rows.fieldnames]
    stock = {}
    for row in rows:
        sku = (row.get("sku") or "").strip()
        if not sku:
            continue
        raw = row["qty"] if row.get("qty") not in (None, "") else row["available"]
        stock[sku] = int(raw)
    return stock

