    description: str
    unit_price: Decimal
    quantity: int = 1
    discount_pct: Decimal = Decimal("0")  # percentage points: 10 means 10%

    @property
    def total(self):
        gross = _money(self.unit_price) * self.quantity
        discount = _money(self.discount_pct)
        return (gross * (1 - discount / 100)).quantize(CENT, rounding=ROUND_HALF_UP)


