"""Minimal qpdf --check stand-in for confirmation PDF checks."""
import sys
from pathlib import Path


def is_pdf(data):
    if not data.startswith(b"%PDF-"):
        return False
    if b"%%EOF" not in data[-2048:]:
        return False
    compact = data.replace(b" ", b"")
    return b"/Type/Page" in compact and b"/Font" in data


def main(argv):
    if "--check" not in argv or len(argv) < 3:
        sys.stderr.write("usage: qpdf --check FILE\n")
        return 2
    path = argv[-1]
    data = Path(path).read_bytes()
    if is_pdf(data):
        sys.stdout.write("PDF is well-formed\n")
        return 0
    sys.stderr.write("invalid PDF\n")
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))

