def _unescape_pdf_string(raw):
    raw = raw.replace(b"\\n", b"\n").replace(b"\\r", b"\r").replace(b"\\t", b"\t")
    raw = raw.replace(b"\\(", b"(").replace(b"\\)", b")").replace(b"\\\\", b"\\")
    return raw.decode("latin-1")


def _extract_text_from_pdf_bytes(pdf_bytes):
    """Stdlib fallback for agents that do not have poppler installed."""
    pieces = []
    for match in re.finditer(rb"stream\r?\n(.+?)\r?\nendstream", pdf_bytes, re.DOTALL):
        data = match.group(1)
        try:
            data = zlib.decompress(data)
        except zlib.error:
            pass
        for token in re.finditer(rb"\((?:\\.|[^\\)])*\)\s*Tj|T\*", data):
            tok = token.group(0)
            if tok == b"T*":
                pieces.append("\n")
                continue
            literal = re.match(rb"\((?:\\.|[^\\)])*\)", tok).group(0)[1:-1]
            pieces.append(_unescape_pdf_string(literal))
        pieces.append("\n")
    return "".join(pieces)


def _pdf_text(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    try:
        result = subprocess.run(
            ["pdftotext", "-layout", str(path), "-"],
