def _decode_pdf_literal(raw):
    def octal(match):
        return bytes([int(match.group(1), 8) & 0xFF])

    raw = re.sub(rb"\\([0-7]{1,3})", octal, raw)
    raw = (
        raw.replace(b"\\n", b"\n")
        .replace(b"\\r", b"\r")
        .replace(b"\\t", b"\t")
        .replace(b"\\b", b"\b")
        .replace(b"\\f", b"\f")
        .replace(b"\\(", b"(")
        .replace(b"\\)", b")")
        .replace(b"\\\\", b"\\")
    )
    return raw.decode("latin-1")


def _pdf_text_from_bytes(pdf_bytes):
    """Read text operators out of a simple (optionally flate) PDF."""

    def strings_in(data):
        return [
            _decode_pdf_literal(match.group(0)[1:-1])
            for match in re.finditer(rb"\((?:\\.|[^\\)])*\)", data)
        ]

    chunks = strings_in(pdf_bytes)
    for match in re.finditer(rb"stream\r?\n(.*?)\r?\nendstream", pdf_bytes, re.DOTALL):
        data = match.group(1)
        try:
            data = zlib.decompress(data)
        except zlib.error:
            pass
        chunks.extend(strings_in(data))
    return "\n".join(chunks)


def _pdf_text(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    try:
        result = subprocess.run(
            ["pdftotext", "-layout", str(path), "-"],
            capture_output=True,
