import re
import zlib
from datetime import datetime

import pytest

from src.clinic.bookings import Booking
from src.clinic.confirmation import render_confirmation

pytestmark = pytest.mark.integration

BOOKING = Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30))


def _unescape_pdf_string(s):
    def repl(m):
        esc = m.group(0)
        mapping = {
            b"\\n": b"\n",
            b"\\r": b"\r",
            b"\\t": b"\t",
            b"\\b": b"\b",
            b"\\f": b"\f",
            b"\\(": b"(",
            b"\\)": b")",
            b"\\\\": b"\\",
        }
        if esc in mapping:
            return mapping[esc]
        if esc.startswith(b"\\") and esc[1:].isdigit():
            return bytes([int(esc[1:], 8)])
        return esc[1:]

    s = re.sub(rb"\\[nrtbf()\\]|\\[0-7]{1,3}", repl, s)
    return s.decode("latin-1")


def _content_streams(pdf_bytes):
    streams = []
    for m in re.finditer(rb"stream\r?\n(.*?)(?:\r?\n)endstream", pdf_bytes, re.DOTALL):
        data = m.group(1)
        try:
            data = zlib.decompress(data)
        except zlib.error:
            pass
        streams.append(data)
    return streams


def _pdf_text(pdf_bytes):
    parts = []
    for data in _content_streams(pdf_bytes):
        for m in re.finditer(rb"\(((?:\\.|[^\\)])*)\)\s*Tj", data):
            parts.append(_unescape_pdf_string(m.group(1)))
        for m in re.finditer(rb"\[(.*?)\]\s*TJ", data, re.DOTALL):
            for sm in re.finditer(rb"\(((?:\\.|[^\\)])*)\)", m.group(1)):
                parts.append(_unescape_pdf_string(sm.group(1)))
    return "\n".join(parts)


def test_confirmation_names_patient_and_time():
    text = _pdf_text(render_confirmation(BOOKING))
    assert "Giulia Conti" in text
    assert "Monday 5 October 2026, 09:30" in text


def test_confirmation_explains_how_to_cancel():
    text = _pdf_text(render_confirmation(BOOKING))
    assert "24 hours" in text


def _qpdf_style_check(pdf_bytes):
    if not pdf_bytes.startswith(b"%PDF-"):
        return False, "missing %PDF- header"
    tail = pdf_bytes.rstrip(b"\r\n \t")
    if not tail.endswith(b"%%EOF"):
        return False, "missing %%EOF"
    matches = list(re.finditer(rb"startxref\s+(\d+)", pdf_bytes))
    if not matches:
        return False, "missing startxref"
    offset = int(matches[-1].group(1))
    at = pdf_bytes[offset : offset + 20]
    if not (at.startswith(b"xref") or re.match(rb"\d+\s+\d+\s+obj", at)):
        return False, f"startxref offset {offset} does not point to xref"
    for m in re.finditer(rb"/Filter\s*/FlateDecode", pdf_bytes):
        pass
    for data in re.finditer(rb"stream\r?\n(.*?)(?:\r?\n)endstream", pdf_bytes, re.DOTALL):
        chunk = data.group(1)
        try:
            zlib.decompress(chunk)
        except zlib.error:
            if chunk.startswith(b"x") or chunk.startswith(b"\x78"):
                return False, "flate stream did not decompress"
    return True, ""


def test_confirmation_is_a_well_formed_pdf():
    ok, reason = _qpdf_style_check(render_confirmation(BOOKING))
    assert ok, reason

