#!/usr/bin/env python3
"""Minimal qpdf --check stand-in."""
import sys
from pathlib import Path


def main():
    args = sys.argv[1:]
    if "--check" not in args or len(args) < 2:
        sys.exit(1)
    path = args[-1]
    data = Path(path).read_bytes()
    if not data.startswith(b"%PDF-") or b"%%EOF" not in data:
        sys.stderr.write("WARNING: file is damaged\n")
        sys.exit(2)
    sys.exit(0)


if __name__ == "__main__":
    main()

